"use client"

import type * as React from "react"
import { cn } from "cn"
import {
  DateField as DateFieldPrimitive,
  DateInput,
  DateSegment,
  FieldError,
  Label,
  Text,
  TimeField as TimeFieldPrimitive,
  type DateFieldProps,
  type DateValue,
  type TimeFieldProps,
  type TimeValue,
} from "react-aria-components"

const inputClassName =
  "flex h-8 w-full min-w-0 items-center rounded-lg border border-input bg-transparent px-2.5 py-1 text-base transition-colors outline-none data-[focus-within]:border-ring data-[focus-within]:ring-3 data-[focus-within]:ring-ring/50 data-[disabled]:pointer-events-none data-[disabled]:opacity-50 data-[invalid]:border-destructive data-[invalid]:ring-3 data-[invalid]:ring-destructive/20 md:text-sm dark:bg-input/30"

const segmentClassName =
  "rounded-sm px-0.5 tabular-nums caret-transparent outline-none data-[placeholder]:text-muted-foreground data-[type=literal]:px-0 data-[type=literal]:text-muted-foreground data-[focused]:bg-primary data-[focused]:text-primary-foreground"

type Extra = {
  className?: string
  label?: React.ReactNode
  description?: React.ReactNode
  errorMessage?: string
}

function FieldChrome({ description, errorMessage }: Pick<Extra, "description" | "errorMessage">) {
  return (
    <>
      <DateInput data-slot="date-field-input" className={inputClassName}>
        {(segment) => <DateSegment segment={segment} className={segmentClassName} />}
      </DateInput>
      {description !== undefined && <Text slot="description" className="text-sm text-muted-foreground">{description}</Text>}
      <FieldError className="text-sm text-destructive">{errorMessage}</FieldError>
    </>
  )
}

/** content.date: React Aria DateField (segmented, locale-aware). granularity and state.invalid pass through. */
function DateField<T extends DateValue>({
  className,
  label,
  description,
  errorMessage,
  ...props
}: Omit<DateFieldProps<T>, "className"> & Extra) {
  return (
    <DateFieldPrimitive data-slot="date-field" className={cn("group flex w-full flex-col gap-2", className)} {...props}>
      {label !== undefined && <Label className="text-sm leading-none font-medium select-none">{label}</Label>}
      <FieldChrome description={description} errorMessage={errorMessage} />
    </DateFieldPrimitive>
  )
}

/** content.time: React Aria TimeField with the same anatomy. */
function TimeField<T extends TimeValue>({
  className,
  label,
  description,
  errorMessage,
  ...props
}: Omit<TimeFieldProps<T>, "className"> & Extra) {
  return (
    <TimeFieldPrimitive data-slot="time-field" className={cn("group flex w-full flex-col gap-2", className)} {...props}>
      {label !== undefined && <Label className="text-sm leading-none font-medium select-none">{label}</Label>}
      <FieldChrome description={description} errorMessage={errorMessage} />
    </TimeFieldPrimitive>
  )
}

export { DateField, TimeField }
